INSERT INTO `mount` (`Name`, `SourceText`, `Description`, `ID`, `MountTypeID`, `Flags`, `SourceTypeEnum`, `SourceSpellID`, `PlayerConditionID`, `MountFlyRideHeight`, `UiModelSceneID`, `MountSpecialRiderAnimKitID`, `MountSpecialSpellVisualKitID`, `VerifiedBuild`) VALUES
('Stormgilded Celestial', '|cFFFFD200In-Game Shop|r', 'Gilded in thunder, chosen by destiny. Golden lightning wraps its hooves, piercing the sky like tearing through night. Legends tie it closely to Emperor Shaohao.', 2743, 424, 64, 9, 1258574, 0, 0, 4, 0, 249025, 65727),
('Thunderhoof Celestial', '|cFFFFD200In-Game Shop|r', 'After the Thunder King\'s fall, his lingering thunder merged with the spirit of a white dragon. It strides on azure lightning, clouds swirling in its wake-where tyranny once reigned, now guardian light remains.', 2742, 424, 64, 9, 1258573, 0, 0, 4, 0, 248910, 65727),
('Bronze Gravewing', '|cFFFFD200Achievement: |rMaster of the Turbulent Timeways IV|n|cFFFFD200Category:|r Timewalking|n', 'While dark and ominous is the preferred aesthetic of those who reside in Revendreth, there are some who still favor gleaming luster.', 2798, 424, 0, 2, 1261681, 0, 0, 4, 0, 0, 65727),
('Bronze Corpsefly', '|cFFFFD200Achievement: |rMaster of the Turbulent Timeways IV|n|cFFFFD200Category:|r Timewalking', 'It takes a great deal of effort to decorate a corpsefly, but some would say the efforts are worth it.', 2797, 424, 128, 2, 1261677, 0, 0, 4, 0, 0, 65727),
('Bronze Aquilon', '|cFFFFD200Achievement: |rMaster of the Turbulent Timeways IV|n|cFFFFD200Category:|r Timewalking|n|n', 'The reliable steeds of Bastion are designed to mirror the proud and noble warriors of the Ascended.', 2796, 424, 0, 0, 1261671, 0, 0, 4, 0, 0, 65727),
('Bronze Wilderling', '|cFFFFD200Achievement: |rMaster of the Turbulent Timeways IV|n|cFFFFD200Category:|r Timewalking|n|n', 'The regal wilderlings twist through the sky, free as the unbound magic that sustains their flight.', 2795, 424, 128, 0, 1261668, 0, 0, 4, 0, 0, 65727),
('Big Slick in the City', '|cFFFFD200Quest:|r Snailed It|n|cFFFFD200Zone: |rZaralek Cavern', 'Big heart, big dreams, Big Slick.', 1729, 230, 0, 1, 408313, 0, 0, 4, 0, 0, 65727);
